F=/scratch/jjyeung/orch_n30/fb_pack
mkdir -p $F/pointrec/work; cp $F/donorrev/AGENTS.md $F/pointrec/AGENTS.md; echo  | base64 -d > $F/pointrec/PROMPT.md; sha256sum $F/pointrec/PROMPT.md | cut -c1-12
ls -la $F/in/pointing/ 2>&1 | head -4
cd $F/pointrec && tmux new-session -d -s fbp_pointrec "OMP_NUM_THREADS=8 MKL_NUM_THREADS=8 OPENBLAS_NUM_THREADS=8 nice -n 10 timeout 5400 agent -p -f --sandbox disabled --trust --model claude-opus-5-5-xhigh 'Read PROMPT.md in this folder and carry out the task it describes. Write only in this folder.' > $F/pointrec/cursor.log 2>&1" </dev/null >/dev/null 2>&1
sleep 3; tmux ls | grep fbp | cut -c1-24; date -u +%TZ
